#![allow(unused_imports)]
use vstd::prelude::*;

#[trusted]
#[requires(a.len() > 0)]
#[ensures(forall(|i: usize| i < a.len() ==> result >= a[i]))]
#[ensures(exists(|i: usize| i < a.len() && result == a[i]))]
fn max_array(a: &Vec<i32>) -> i32 {
    // Since the array is guaranteed to be non-empty, we can safely unwrap.
    *a.iter().max().unwrap()
}

